<?php include __DIR__.'/../layout/header.php'; ?><div class="head"><h1><?=$title?></h1><?php if($_SESSION['user']['role']==='student'): ?><a class="btn" href="index.php?page=report">+ New Report</a><?php endif; ?></div><div class="card table-wrap"><table><tr><th>Title</th><th>Reporter</th><th>Category</th><th>Priority</th><th>Status</th><th>Assigned</th><th></th></tr><?php foreach($reports as $r): ?><tr><td><?=e($r['title'])?></td><td><?=e($r['reporter']??$_SESSION['user']['name'])?></td><td><?=e($r['category'])?></td><td><?=e($r['priority'])?></td><td><?=e(ucwords(str_replace('_',' ',$r['status'])))?></td><td><?=e($r['staff_name']??'Unassigned')?></td><td><a href="index.php?page=view&id=<?=$r['id']?>">View</a></td></tr><?php endforeach; ?><?php if(!$reports): ?><tr><td colspan="7">No reports found.</td></tr><?php endif; ?></table></div><?php include __DIR__.'/../layout/footer.php'; ?>
